export const binarySearchMeta={slug:'algorithms/binary-search',title:'Binary and Monotonic Search',description:'Exact search, first-true boundaries, answer-space feasibility and transformed order with explicit interval contracts.',date:'2026-04-08',updated:'2026-10-18',topicPath:['algorithms'],tags:['binary search','lower bound','monotonic predicate','feasibility','bisect','rotated array'],prototype:true,visibility:'public',kind:'dense-topic',related:['algorithms/windows','algorithms/arrays']};
export const binarySearchAliases=[];
export const binarySearchSections=[['predicate','Search a boundary, not necessarily an input value'],['exact','Exact search uses a closed candidate interval'],['exact-lab','Find 23 in three probes'],['boundary','First true uses a half-open interval'],['bound-lab','A duplicate is not an instruction to stop'],['answers','Search feasible answers'],['transforms','Order must survive the transformation'],['termination','Interval updates must make progress'],['practice','Test boundaries before trusting logarithmic time'],['sources','Sources and connected topics']];
const exactValues=[2,5,8,12,16,23,38,56,72,91],exactFrames=exactSearchTrace(exactValues,23);
const exactBody=f=>`${cells(exactValues,f.middle===null?[]:[f.middle],Array.from({length:Math.max(0,f.right-f.left+1)},(_,i)=>f.left+i))}<p>${f.message}</p><p>Probe interval: [${f.left},${f.right}]. ${f.result===null?`Next candidate interval: [${f.nextLeft},${f.nextRight}].`:`Returned index: ${f.result}.`}</p><p>Filled cells are candidates before this probe. The outline marks the probe; eliminated cells retain their indices for reference.</p>`;
const a=[1,2,2,2,5,8,9],frames=lowerBoundTrace(a,2);
const body=f=>`${cells(a,f.middle===null?(f.left===f.right&&f.left<a.length?[f.left]:[]):[f.middle],Array.from({length:Math.max(0,f.right-f.left)},(_,i)=>f.left+i))}<p>${f.message}</p><div class="scene-stats"><span>Left <output>${f.left}</output></span><span>Right, exclusive <output>${f.right}</output></span></div><p>The shaded interval is the next interval after the probe. The blue outline marks the probed position, or the returned position at completion. A probed position may already have been excluded.</p>`;
export function binarySearchReader(link){return topic(binarySearchMeta,binarySearchSections,'Find the transition, then prove that each comparison keeps it.',`
<p>Binary search removes a large part of the search space after each probe. This works because a comparison orders the remaining possibilities. The values need not literally sit in a sorted array: a candidate capacity or speed can also have a monotone feasibility predicate.</p><p>A logarithmic-time requirement is a clue, not proof that binary search applies. Define the searched domain, the predicate's direction and the interval convention before choosing update rules.</p>
${section('predicate','Search a boundary, not necessarily an input value',`${'<figure class="dense-boundary"><p><code>false … false | true … true</code></p><figcaption>First-true search locates this transition. Either side can be empty.</figcaption></figure>'}<p>A sorted array's predicate a[i]≥target has that form. So does “this capacity completes the fixed workload within D days” if increasing capacity cannot hurt under the specified rules. An arbitrary boolean condition that alternates true and false does not.</p>${table('What is the search domain?',['Question','Domain','Predicate/result'],[['Find any exact value','Array indices','Comparison with target'],['Find first occurrence','Array indices plus end sentinel','First a[i]≥target, then verify equality'],['Minimum feasible capacity','Integer capacities','Feasible(candidate) changes false→true'],['Latest usable timestamp','Sorted timestamps','Last time≤query'],['Maximum feasible value','Candidate range','Usually true→false; reverse the boundary convention']])}`)}
${section('exact','Exact search uses a closed candidate interval',`<p>Start [left,right]=[0,n−1]. If a target exists, some eligible occurrence remains inside that closed interval. Equality may return immediately when any occurrence suffices. A smaller middle value excludes every index through middle; a larger value excludes every index from middle onward.</p><pre><code>left, right = 0, len(nums) - 1
while left &lt;= right:
    middle = left + (right - left) // 2
    if nums[middle] == target:
        return middle
    if nums[middle] &lt; target:
        left = middle + 1
    else:
        right = middle - 1
return -1</code></pre><p>The empty array starts with right=−1 and does not enter the loop. The returned −1 is an index sentinel, not an array access. Returning at equality is insufficient if the question asks for the first or last equal element.</p>`)}
${traceLab('exact-lab','Find 23 in three probes','Search [2,5,8,12,16,23,38,56,72,91] for 23 with closed endpoints and a floor midpoint. Initial display is the completed result.',exactFrames,exactFrames.length-1,exactBody,'Filled cells show the current closed interval; the outline marks the probe.')}
${table('Three probes, not three array scans',['Closed interval','Middle index/value','Comparison','Next action'],[['[0,9]','4 / 16','23 > 16','Keep [5,9]'],['[5,9]','7 / 56','23 < 56','Keep [5,6]'],['[5,6]','5 / 23','Equal','Return index 5']])}
<p>The comparison uses the middle value; the returned result is its index. Halving continues until equality or an empty interval, not until exactly two values remain. The extra element at index 6 need not be inspected once index 5 matches.</p>
<p>Worked input: ${cite('https://www.youtube.com/watch?v=kp3fCihUXEg','Top 7 Algorithms for Coding Interviews Explained Simply')}. The step-controlled diagram computes each interval directly; playback timing is illustrative.</p>
${section('boundary','First true uses a half-open interval',`<p>This lower-bound variant uses [left,right), initially [0,n). Positions before left are known too small; positions from right onward are known large enough. The answer may equal n, meaning insertion after the entire array. Never index a[n].</p><pre><code>left, right = 0, len(nums)
while left &lt; right:
    middle = left + (right - left) // 2
    if nums[middle] &gt;= target:
        right = middle
    else:
        left = middle + 1
return left</code></pre><p>right=middle keeps a successful middle as the possible boundary. Under left&lt;right, middle is strictly below right, so that update still shrinks the interval. By contrast, left=middle can fail to progress when two endpoints are adjacent.</p><p>A closed-interval first-true variant saves each successful candidate before discarding it from the remaining search. Initialize the answer to one past the upper bound. All-false returns that sentinel; all-true returns the lower bound. This implementation and the half-open form locate the same boundary under their respective interval contracts.</p><pre><code>def first_true(left, right, condition):
    answer = right + 1
    while left &lt;= right:
        middle = left + (right - left) // 2
        if condition(middle):
            answer = middle
            right = middle - 1
        else:
            left = middle + 1
    return answer</code></pre><p>For a last-true search with a true-to-false predicate, save a successful candidate and move left to middle+1; on false, move right to middle−1. The no-answer sentinel is one below the initial lower bound. Do not reverse the first-true updates without also changing the predicate and sentinel.</p><p>First equal is lower_bound followed by an in-bounds equality check. Upper bound changes the predicate to a[i]&gt;target; upper−lower counts equal values. The last value ≤target is upper_bound−1, with −1 meaning none.</p>${traceLab('bound-lab','A duplicate is not an instruction to stop','Find first value ≥2 in [1,2,2,2,5,8,9]. The first successful middle is index 3, but earlier 2s remain possible. Initial display shows the completed boundary.',frames,frames.length-1,body)}`)}
${section('answers','Search feasible answers',`<p>The answer may be absent from the input. For shipping indivisible positive loads in their existing order within D days, any capacity below max(loads) is impossible. sum(loads) is feasible for D≥1. A greedy feasibility pass fills each day until the next load would exceed capacity, then starts another day.</p><p>Increasing capacity cannot require more days under this model. Binary search can therefore find the least feasible integer capacity. The proof depends on ordered, unsplit loads and a specified daily rule; adding unrelated constraints may change the predicate.</p><p>For positive integer workloads and a speed v, a time check may sum ceil(workload/v). Larger v cannot increase that sum. Integer (workload+v−1)//v avoids floating rounding under safe arithmetic. If the time budget is smaller than the number of nonempty workloads when each requires a distinct unit of time, no finite speed works under that model.</p>${eq("T(R)=O\\!\\left(C_{\\mathrm{pred}}(1+\\log_2 R)\\right),\\qquad R\\ge1","R is the integer candidate count; Cpred bounds one predicate evaluation under a consistent monotone contract. A linear n-item check gives O(n(1+log R)), not O(log R) total. Empty domains require a separate no-candidate result.")}<p>Find bounds that contain the boundary and a feasible upper endpoint when needed. Exponential expansion can discover a bound only if eventual feasibility and overflow handling are established. A real-valued search also needs a tolerance or iteration rule; integer adjacent-endpoint termination is not interchangeable.</p>`)}
${section('transforms','Order must survive the transformation',`<p>A rectangular matrix can be flattened by <code>row = middle // columns</code> and <code>column = middle % columns</code> only when its row-major sequence is globally sorted. Sorting each row individually is insufficient if the next row begins below the previous row's end. Handle empty dimensions before division/indexing.</p><p>A rotated sorted array has an ordered side that a comparison can identify when values are distinct. Test whether target lies within that ordered side's value bounds, then keep or discard it. Duplicates can hide which side is ordered; ambiguous equal boundaries can force linear worst-case work.</p><p>Time-based retrieval sorts versions by timestamp per key, then finds the last timestamp not exceeding the query. Median partition search across two sorted arrays is another transformed boundary: the left partition's maxima must not exceed the right partition's minima. Its partition sizes and edge sentinels need a separate proof, not the ordinary exact-search loop.</p>`)}
${section('termination','Interval updates must make progress',`<p>Inclusive [left,right] uses left≤right and typically ±1 updates. Half-open [left,right) uses left&lt;right and may retain middle as right. “Always move both sides by one” and “never use right=middle” are both misleading rules without a convention.</p><p>For nonnegative indices in fixed-width arithmetic, left+(right−left)//2 avoids overflowing the sum left+right when the difference is representable. Arbitrary signed answer domains may need a safer midpoint policy. Python's arbitrary-precision integers do not have that fixed-width overflow.</p><p>The predicate must be consistent across probes. A noisy measurement or changing external state does not automatically produce a valid monotone boundary, even if its average trend looks monotone.</p>`)}
${section('practice','Test boundaries before trusting logarithmic time',`<p>Test empty and singleton domains; all false; all true; answer at either end; duplicates; no exact match; a feasible value between input values; and predicates at the proposed limits. Check both the returned position and whether it is a real match or merely an insertion point.</p><p>Write the monotone sentence, interval invariant and strictly decreasing interval width. These three statements are more reusable than memorizing one loop. <a href="${link('algorithms/windows')}">Two-pointer elimination →</a> also discards candidates using order, but normally traverses them instead of halving the interval.</p>`)}
${section('sources','Sources and connected topics',`<p>${cite('https://docs.python.org/3/library/bisect.html','Python lower/upper insertion boundaries')}</p><p><a href="${link('algorithms/choosing')}">Choosing an algorithm →</a> connects constraints to proof obligations.</p>`)}
`);}
